import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Fetch Single Mail (Gmail)","description":"","frontmatter":{"prev":{"text":"Fetch Mail (Gmail)","link":"/documentation/field-types/google-service-gmail/fetch-mail-gmail"},"next":{"text":"Gmail API Search Queries","link":"/documentation/field-types/google-service-gmail/gmail-api-search-queries"}},"headers":[],"relativePath":"documentation/field-types/google-service-gmail/fetch-single-mail-gmail.md","filePath":"documentation/field-types/google-service-gmail/fetch-single-mail-gmail.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/google-service-gmail/fetch-single-mail-gmail.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fetch-single-mail-gmail" tabindex="-1">Fetch Single Mail (Gmail) <a class="header-anchor" href="#fetch-single-mail-gmail" aria-label="Permalink to “Fetch Single Mail (Gmail)”">​</a></h1><p>Retrieve a single, specific email from Gmail using a message ID or targeted search query, optimized for fast OTP extraction, authentication links, and single-record parsing.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>While <a href="/documentation/field-types/google-service-gmail/fetch-mail-gmail.html">Fetch Mail (Gmail)</a> is engineered for processing email collections, <strong>Fetch Single Mail (Gmail)</strong> is tailored for point-to-point verification where you need exactly one targeted message (e.g., retrieving the latest two-factor authentication code or password reset token).</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Google Service Account</strong></td><td>Dropdown</td><td>Authorized Google account with Gmail permissions.</td><td>Yes</td></tr><tr><td><strong>Enable Max Results</strong></td><td>Toggle Switch</td><td>Restricts results to a single message (recommended ON).</td><td>No</td></tr><tr><td><strong>Max Results Count</strong></td><td>Number Input</td><td>Set to <code>1</code> for single-message workflows.</td><td>No</td></tr><tr><td><strong>Include Spam/Trash</strong></td><td>Toggle Switch</td><td>Checks Spam and Trash folders.</td><td>No</td></tr><tr><td><strong>Enable Retry on Failure</strong></td><td>Toggle Switch</td><td>Re-attempts execution on transient API connectivity errors.</td><td>No</td></tr><tr><td><strong>Max Retries (Failure)</strong></td><td>Number Input</td><td>Number of network retry attempts.</td><td>When retry enabled</td></tr><tr><td><strong>Retry Until Mail Received</strong></td><td>Toggle Switch</td><td>Polls the inbox until the expected email arrives.</td><td>No</td></tr><tr><td><strong>Max Retries (Until Received)</strong></td><td>Number Input</td><td>Number of polling checks before timing out.</td><td>When polling enabled</td></tr><tr><td><strong>Timeout</strong></td><td>Number Input</td><td>Seconds to pause between polling checks.</td><td>No</td></tr><tr><td><strong>Enable Regex Filter</strong></td><td>Toggle Switch</td><td>Extracts targeted tokens or numbers using regex patterns.</td><td>No</td></tr><tr><td><strong>Regular Expression</strong></td><td>Text Input</td><td>Regex query (e.g., <code>\\b\\d{6}\\b</code>).</td><td>When regex enabled</td></tr><tr><td><strong>Regex Replace</strong></td><td>Text Input</td><td>Optional replacement string for matched pattern.</td><td>No</td></tr><tr><td><strong>Remove UNREAD Label</strong></td><td>Toggle Switch</td><td>Automatically marks email as read upon retrieval.</td><td>No</td></tr><tr><td><strong>Search Query</strong></td><td>Default Value</td><td>Gmail query syntax to locate the target message.</td><td>No</td></tr></tbody></table><hr><h2 id="otp-workflows" tabindex="-1">Targeted OTP &amp; Verification Workflows <a class="header-anchor" href="#otp-workflows" aria-label="Permalink to “Targeted OTP &amp; Verification Workflows”">​</a></h2><p>Extracting an automated one-time password during form execution:</p><ol><li><strong>Trigger the Code</strong>: Form action submits an input triggering an email dispatch from the target website.</li><li><strong>Configure Single Fetch</strong>: <ul><li><strong>Search Query</strong>: <code>from:accounts@service.com is:unread</code></li><li><strong>Retry Until Mail Received</strong>: <code>ON</code></li><li><strong>Max Retries</strong>: <code>8</code></li><li><strong>Timeout</strong>: <code>5</code> seconds</li><li><strong>Enable Regex Filter</strong>: <code>ON</code> (<code>\\b\\d{6}\\b</code>)</li><li><strong>Remove UNREAD Label</strong>: <code>ON</code></li></ul></li><li><strong>Execution</strong>: The extension polls Gmail until the message arrives, isolates the 6 digits, and passes them directly to the subsequent OTP form field.</li></ol><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-extracting-latest-security-passcode" tabindex="-1">Example 1: Extracting Latest Security Passcode <a class="header-anchor" href="#example-1-extracting-latest-security-passcode" aria-label="Permalink to “Example 1: Extracting Latest Security Passcode”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: user@example.com</span></span>
<span class="line"><span>Enable Max Results: ON</span></span>
<span class="line"><span>Max Results Count: 1</span></span>
<span class="line"><span>Retry Until Mail Received: ON</span></span>
<span class="line"><span>Max Retries (Until Received): 6</span></span>
<span class="line"><span>Timeout: 5</span></span>
<span class="line"><span>Enable Regex Filter: ON</span></span>
<span class="line"><span>Regular Expression: (?&lt;=Your code is )\\d{6}</span></span>
<span class="line"><span>Remove UNREAD Label: ON</span></span>
<span class="line"><span>Search Query: from:security@bank.com is:unread</span></span></code></pre></div><h3 id="example-2-extracting-account-activation-url" tabindex="-1">Example 2: Extracting Account Activation URL <a class="header-anchor" href="#example-2-extracting-account-activation-url" aria-label="Permalink to “Example 2: Extracting Account Activation URL”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: user@example.com</span></span>
<span class="line"><span>Enable Regex Filter: ON</span></span>
<span class="line"><span>Regular Expression: https://app\\.domain\\.com/activate\\?key=[A-Za-z0-9]+</span></span>
<span class="line"><span>Search Query: subject:&quot;Activate your account&quot; newer_than:1d</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Combine <code>is:unread</code> with <code>newer_than</code></strong>: Always add <code>newer_than:1d</code> or <code>newer_than:1h</code> to ensure outdated historical emails are never matched accidentally.</li><li><strong>Always Mark as Read</strong>: Keep <strong>Remove UNREAD Label</strong> enabled so subsequent test runs or loop iterations don&#39;t re-read past tokens.</li><li><strong>Use Lookbehind in Regex</strong>: Regex lookarounds like <code>(?&lt;=code:\\s*)\\d{6}</code> allow you to isolate raw numeric tokens cleanly.</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/chat.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/fetch-mail-gmail.html">Fetch Mail (Gmail)</a></li><li><img src="/svg/globe.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/gmail-api-search-queries.html">Gmail API Search Queries Guide</a></li><li><img src="/svg/click.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/send-mail-gmail.html">Send Mail (Gmail)</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/services/google-service.html">Google Service Account Setup</a></li></ul>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};